'use strict';
const analysisGraphBuilder=typeof module!=='undefined'?require('./network.js').buildRoadGraph:buildRoadGraph;
function haversineKm(a,b){const r=Math.PI/180,dlat=(b[0]-a[0])*r,dlon=(b[1]-a[1])*r,h=Math.sin(dlat/2)**2+Math.cos(a[0]*r)*Math.cos(b[0]*r)*Math.sin(dlon/2)**2;return 6371.0088*2*Math.atan2(Math.sqrt(h),Math.sqrt(Math.max(0,1-h)))}
function buildHydrantAnalysis(routes,buildings,target,settings={},kmBetween=haversineKm){
 const maxGap=settings.maxGap??250,objective=settings.objective||'distance',g=analysisGraphBuilder(routes,kmBetween),ref=target[0]*Math.PI/180,xScale=111320*Math.cos(ref),yScale=110574;
 const project=p=>[p[1]*xScale,p[0]*yScale];
 const projected=g.edges.map(e=>{const a=project(g.nodes[e.a].p),b=project(g.nodes[e.b].p);return{a,b,dx:b[0]-a[0],dy:b[1]-a[1]}});
 function snap(p){let best=null,bestD=Infinity,q=project(p);for(let i=0;i<g.edges.length;i++){let e=projected[i],len=e.dx*e.dx+e.dy*e.dy,t=len?Math.max(0,Math.min(1,((q[0]-e.a[0])*e.dx+(q[1]-e.a[1])*e.dy)/len)):0,d=(q[0]-e.a[0]-t*e.dx)**2+(q[1]-e.a[1]-t*e.dy)**2;if(d<bestD){bestD=d;let a=g.nodes[g.edges[i].a].p,b=g.nodes[g.edges[i].b].p,point=[a[0]+t*(b[0]-a[0]),a[1]+t*(b[1]-a[1])];best={edge:i,t,point,gap:kmBetween(p,point)*1000}}}return best}
 const targetSnap=snap(target),validTarget=targetSnap&&targetSnap.gap<=maxGap;
 const reverse=g.nodes.map(()=>[]);g.edges.forEach((e,i)=>{if(e.ab)reverse[e.b].push({node:e.a,edge:i});if(e.ba)reverse[e.a].push({node:e.b,edge:i})});
 const costs=g.nodes.map(()=>Infinity),kms=g.nodes.map(()=>Infinity),mins=g.nodes.map(()=>Infinity),next=g.nodes.map(()=>null),heap=[];
 function push(v){heap.push(v);let i=heap.length-1;while(i){let p=(i-1)>>1;if(heap[p][0]<=v[0])break;heap[i]=heap[p];i=p}heap[i]=v}
 function pop(){let v=heap[0],end=heap.pop();if(heap.length){let i=0;while(i*2+1<heap.length){let c=i*2+1;if(c+1<heap.length&&heap[c+1][0]<heap[c][0])c++;if(heap[c][0]>=end[0])break;heap[i]=heap[c];i=c}heap[i]=end}return v}
 function improve(n,km,min,via){let cost=objective==='time'?min:km;if(cost<costs[n]-1e-10){costs[n]=cost;kms[n]=km;mins[n]=min;next[n]=via;push([cost,n])}}
 if(validTarget){let e=g.edges[targetSnap.edge],minutes=e.km/e.speed*60;if(e.ab)improve(e.a,e.km*targetSnap.t,minutes*targetSnap.t,{seed:true});if(e.ba)improve(e.b,e.km*(1-targetSnap.t),minutes*(1-targetSnap.t),{seed:true});while(heap.length){let [c,n]=pop();if(c!==costs[n])continue;for(const r of reverse[n]){let e=g.edges[r.edge];improve(r.node,kms[n]+e.km,mins[n]+e.km/e.speed*60,{node:n,edge:r.edge})}}}
 const rows=buildings.map((b,i)=>{let s=snap(b.coord),row={building_id:b.id,label:'B'+String(i+1).padStart(3,'0'),lat:b.coord[0],lng:b.coord[1],status:'no_connection',distance_km:null,time_min:null,building_access_m:s?.gap??null,hydrant_access_m:targetSnap?.gap??null,snap:s};if(!validTarget){row.status='hydrant_gap';return row}if(!s||s.gap>maxGap){row.status='access_gap';return row}let e=g.edges[s.edge],choices=[];if(e.ba&&Number.isFinite(costs[e.a]))choices.push({km:e.km*s.t+kms[e.a],min:e.km*s.t/e.speed*60+mins[e.a],node:e.a});if(e.ab&&Number.isFinite(costs[e.b]))choices.push({km:e.km*(1-s.t)+kms[e.b],min:e.km*(1-s.t)/e.speed*60+mins[e.b],node:e.b});if(s.edge===targetSnap.edge){let delta=targetSnap.t-s.t;if((delta>=0&&e.ab)||(delta<=0&&e.ba))choices.push({km:Math.abs(delta)*e.km,min:Math.abs(delta)*e.km/e.speed*60,direct:true})}choices.sort((a,b)=>(objective==='time'?a.min-b.min:a.km-b.km)||(objective==='time'?a.km-b.km:a.min-b.min));let c=choices[0];if(c){row.status='routed';row.distance_km=c.km;row.time_min=c.min;row.choice=c}return row});
 function pathFor(row){if(row.status!=='routed')return[];if(row.choice.direct)return[row.snap.point,targetSnap.point];let out=[row.snap.point],n=row.choice.node;for(let i=0;i<=g.nodes.length;i++){out.push(g.nodes[n].p);if(next[n]?.seed){out.push(targetSnap.point);return out}if(!next[n])return[];n=next[n].node}return[]}
 return{rows,targetSnap,graph:g,pathFor,settings:{maxGap,objective}};
}
// Greedy fixed-radius circles: choose the densest remaining building-centred
// circle, assign each member once, repeat. This is not DBSCAN or an optimum.
function fixedRadiusClusters(points,radiusKm,minCount,kmBetween=haversineKm){if(!(radiusKm>0)||!(minCount>=1))throw Error('Radius and minimum count must be positive');let neighbours=points.map(p=>points.map((q,j)=>kmBetween(p.coord,q.coord)<=radiusKm+1e-10?j:-1).filter(j=>j>=0)),remaining=new Set(points.map((_,i)=>i)),groups=[];while(remaining.size){let best=[],centre=-1;for(const i of remaining){let members=neighbours[i].filter(j=>remaining.has(j));if(members.length>best.length){best=members;centre=i}}if(best.length<minCount)break;groups.push({id:'C'+String(groups.length+1).padStart(2,'0'),coord:points[centre].coord,members:best.map(i=>points[i].id),radiusKm});for(const i of best)remaining.delete(i)}return{groups,unassigned:[...remaining].map(i=>points[i].id)}}
if(typeof module!=='undefined')module.exports={buildHydrantAnalysis,fixedRadiusClusters,haversineKm};
